   if(state.selectionRows!==undefined&&(!Array.isArray(state.selectionRows)||state.selectionRows.length>20000||state.selectionRows.some(n=>!Number.isInteger(n)||n<0||n>1000000)||new Set(state.selectionRows).size!==state.selectionRows.length))bad();
